# sessions and place calls.
DEFAULT_CORS_ORIGINS = [
    "http://localhost:3000",
    "http://127.0.0.1:3000",
    "http://localhost:3001",
    "http://127.0.0.1:3001",
    "http://localhost:4000",
    "http://127.0.0.1:4000",
]


def cors_origins_from_env(raw: str | None) -> list[str]:
    extra = [origin.strip() for origin in (raw or "").split(",") if origin.strip()]
    return list(dict.fromkeys([*DEFAULT_CORS_ORIGINS, *extra]))


def _load_dotenv(path: Path) -> None:
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        os.environ.setdefault(key.strip(), value.strip())


@dataclass(frozen=True)
class Settings:
    repo_root: Path
    live_calls_enabled: bool
    # Which system-of-record adapter to serve from. Both implement the same
    # `SystemOfRecord` interface and pass the same tests; "sqlite" is the default
    # and "yaml" is the reference implementation, kept because having two proves
    # the adapter seam is real rather than decorative.
    record_backend: str = "sqlite"
    # Publishing the decision as a pull request. Unset means rehearsal: the
    # publish endpoint reports the branch and files it would have pushed.
    github_token: str | None = None
    github_repo: str | None = None
    github_base_branch: str = "main"
    cors_origins: list[str] = field(default_factory=lambda: DEFAULT_CORS_ORIGINS.copy())

    @property
    def call_mode(self) -> str:
        return "live" if self.live_calls_enabled else "rehearsal"


def get_settings() -> Settings:
    repo_root = Path(__file__).resolve().parents[2]
    _load_dotenv(repo_root / ".env")
    backend = os.environ.get("RECORD_BACKEND", "sqlite").strip().lower()
    if backend not in ("sqlite", "yaml"):
        raise ValueError(f'RECORD_BACKEND must be "sqlite" or "yaml", got {backend!r}')
    return Settings(
        repo_root=repo_root,
        live_calls_enabled=os.environ.get("LIVE_CALLS", "").strip() == LIVE_CALLS_CONFIRMATION,
        record_backend=backend,
        github_token=os.environ.get("GITHUB_TOKEN", "").strip() or None,
        github_repo=os.environ.get("GITHUB_REPO", "").strip() or None,
        github_base_branch=os.environ.get("GITHUB_BASE_BRANCH", "main").strip() or "main",
        cors_origins=cors_origins_from_env(os.environ.get("CASES_ALLOWED_ORIGINS")),
    )
"""Environment configuration. Rehearsal is the default everywhere."""

from __future__ import annotations

import os
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent


def _load_dotenv(path: Path) -> None:
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key and key not in os.environ:
            os.environ[key] = value


_load_dotenv(REPO_ROOT / ".env")

# Rehearsal is the default. Live calling is an explicit opt-in, never a
# fallback and never triggered by a merely-unset variable.
FAKE_CALLS: bool = os.environ.get("FAKE_CALLS", "1") == "1"

CALLE_API_KEY: str | None = os.environ.get("CALLE_API_KEY")
CALLE_BASE_URL: str = os.environ.get("CALLE_BASE_URL", "https://api.heycall-e.com")
PUBLIC_BASE_URL: str = os.environ.get("PUBLIC_BASE_URL", "http://localhost:8000").strip().rstrip("/")

BUYER_NAME: str = os.environ.get("BUYER_NAME", "Meridian Motors")

# Seconds. The fake waits this long before delivering each quote, so
# consumers are forced to build against the async shape a real call has.
FAKE_MIN_DELAY: float = float(os.environ.get("FAKE_MIN_DELAY", "0.4"))
FAKE_MAX_DELAY: float = float(os.environ.get("FAKE_MAX_DELAY", "2.5"))

# Seconds. A real call sits queued and then runs for a few minutes, so the
# live provider polls CALL-E for the result rather than waiting on a webhook.
# Polling is an outbound request, so it needs no public URL and no tunnel.
CALLE_POLL_INTERVAL: float = float(os.environ.get("CALLE_POLL_INTERVAL", "10"))
CALLE_POLL_TIMEOUT: float = float(os.environ.get("CALLE_POLL_TIMEOUT", "900"))

# Where finished quotes are written. STORE only lives as long as the
# process, so without this a completed call leaves nothing behind.
QUOTES_DIR: Path = Path(os.environ.get("QUOTES_DIR", str(REPO_ROOT / "data" / "quotes")))

# The language the agent speaks. This drives the call, not the script: a
# de-DE locale produced a fully German call even though the task text was
# written in English, so keep it in step with the prompt's language rule.
CALLE_LOCALE: str = os.environ.get("CALLE_LOCALE", "en-US")
# Where the number being dialled lives — a routing detail, not a language.
CALLE_REGION: str = os.environ.get("CALLE_REGION", "DE")
# Slice B (backend + packages) and Slice A (ui). One entry point for both.
#
# `./run.sh` does all of this in one command; these targets are the pieces.
#
#   make install    once, per machine
#   make test       everything that does not touch the network
#   make api        the FastAPI process on :8010  (override with API_PORT=)
#   make ui         the cockpit on :3000
#   make fixtures   re-export schema, TypeScript types and the UI fixture bundle
#
# The ROS install on some machines registers pytest plugins that fail to import;
# PYTEST_DISABLE_PLUGIN_AUTOLOAD keeps the run reproducible everywhere.

PY := .venv/bin/python
# Override if the port is taken:  make api API_PORT=9000
API_PORT ?= 8010
PYTEST := PYTEST_DISABLE_PLUGIN_AUTOLOAD=1 PYTHONPATH= $(PY) -m pytest

# Next 16 needs Node >= 20.9 and several machines here default to 18. Run every
# node command through nvm using .nvmrc, falling back to whatever node is on
# PATH if nvm is not installed.
NODE := bash -lc 'cd ui && { source "$$NVM_DIR/nvm.sh" 2>/dev/null && nvm use >/dev/null 2>&1; };

.PHONY: install api ui db fixtures test test-backend detect build clean

install:
	$(PY) -m pip install -e '.[dev]'
	$(NODE) npm install'

# Rebuild the SQL system of record from the seed YAML. The .db is a build
# artifact and is gitignored -- the YAML is the source.
db:
	PYTHONPATH= $(PY) -m backend.record.seed_db

api: db
	PYTHONPATH= $(PY) -m uvicorn backend.api.main:app --reload --port $(API_PORT)

ui:
	$(NODE) npm run dev'

# Regenerate the three consumers of the frozen contract. Run after any change to
# packages/contracts/models.py, and commit the output.
fixtures:
	PYTHONPATH= $(PY) -m packages.contracts.export

test: test-backend
	$(NODE) npx tsc --noEmit'

test-backend:
	$(PYTEST) backend/tests -q

# B4 -- scan the system of record and open a case for anything at risk.
detect:
	PYTHONPATH= $(PY) -m backend.detect.shortage_detector

build:
	$(NODE) npm run build'

clean:
	rm -rf ui/.next cases/CASE-00*/ backend/record/*.db
	find . -name __pycache__ -not -path './.venv/*' -exec rm -rf {} + 2>/dev/null || true

