    getPlan(caseId).then(setPlan).catch(() => setPlan(null))
  }, [caseId])

  // The case is joined server-side, so one poll refreshes candidates, claims and
  // the priced plans together -- no partial screen while a phase lands.
  React.useEffect(() => {
    if (!LIVE) return
